import * as Story from './story.mjs';

const $=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg',KEY='valwood.quest-story-studio.v1';
const copy=x=>structuredClone(x),el=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;};
const labels={beat:'Story beat',chapter:'Chapter',quest:'Quest',objective:'Objective',dialogue:'Conversation',line:'Dialogue line',entity:'Scene entity',flag:'Story flag',counter:'Counter / reward',rule:'Event rule',encounter:'Encounter',trigger:'World trigger',project:'Story project'};
const collection={quest:'quests',dialogue:'dialogues',entity:'entities',flag:'flags',counter:'counters',rule:'rules',encounter:'encounters',trigger:'triggers'};
const friendly={Interact:'Interact',TriggerEnter:'Enter a trigger',Kill:'Defeat an actor',Objective:'Objective event',EncounterFinished:'Encounter ends',DialogueChoice:'Dialogue choice',Flag:'Story flag',Counter:'Counter',Quest:'Quest state',Encounter:'Encounter state',EntityActive:'Entity active',CooldownReady:'Rule ready',EventValue:'Incoming event value',Equal:'equals',NotEqual:'does not equal',Less:'is less than',AtLeast:'is at least',SetFlag:'Set story flag',SetCounter:'Set counter',AddCounter:'Add counter / reward',Speak:'Open conversation',ActivateEntity:'Set entity active',StartEncounter:'Start encounter',StartTraining:'Start training',SetQuest:'Set quest state',SetEncounter:'Set encounter state',SetCooldown:'Set rule cooldown (ms)'};
let doc=Story.blank(),selected={kind:'project',id:'',parent:''},back=[],forward=[],dirty=false,savedJSON='',draftTimer,drag=null,preview=null,previewRevision='',storyAt='',fieldSerial=0,activeDialogue='',sourceName='',storageBlocked=false,recoveredDraft=false;
const view={mode:'story',zoom:1,x:40,y:40,width:800,height:600};let graphNodes=[],graphEdges=[];
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),5000);}
function safeErrors(){try{return Story.validate(doc);}catch{return ['The document structure is invalid. Open a supported story project.'];}}
function checkpoint(){storageBlocked=false;back.push(copy(doc));if(back.length>60)back.shift();forward=[];}
function titleOf(kind,item){return item?.title||item?.name||item?.text||(labels[kind]||kind);}
function locate(kind,id,parent=selected.parent){if(kind==='project')return doc;if(kind==='chapter')return doc.chapters.find(x=>x.id===id);if(kind==='beat')return doc.beats.find(x=>x.id===id);if(kind==='objective')return doc.native.quests.flatMap(q=>q.objectives).find(x=>x.id===id);if(kind==='line')return (parent?doc.native.dialogues.find(t=>t.id===parent)?.lines:doc.native.dialogues.flatMap(t=>t.lines))?.find(x=>x.id===id);return doc.native[collection[kind]]?.find(x=>x.id===id);}
function questFor(id){return doc.native.quests.find(q=>q.objectives.some(o=>o.id===id));}function talkFor(id,parent=selected.parent){return parent?doc.native.dialogues.find(t=>t.id===parent):doc.native.dialogues.find(t=>t.lines.some(l=>l.id===id));}
function currentChapter(){const item=locate(selected.kind,selected.id);return selected.kind==='chapter'?selected.id:item?.chapter||questFor(selected.id)?.chapter||talkFor(selected.id)?.chapter||doc.chapters[0].id;}
function button(text,run,cls=''){const b=el('button',cls,text);b.type='button';b.onclick=run;return b;}
function hint(parent,text,cls='help'){parent.append(el('p',cls,text));}
function heading(parent,text,run,addLabel='＋ Add'){const h=el('div','field-heading');h.append(el('span','',text));if(run)h.append(button(addLabel,run));parent.append(h);return h;}
function change(rebuild=true,inspect=false){
 const errors=safeErrors();dirty=JSON.stringify(doc)!==savedJSON;$('dirty').classList.toggle('clean',!dirty);$('dirty').title=dirty?'Changes since last project save':'Project file saved';$('project-name').textContent=doc.title;$('project-logline').textContent=doc.logline||'Give the world a reason to move.';$('undo').disabled=!back.length;$('redo').disabled=!forward.length;$('export').disabled=!!errors.length;
 $('autosave-state').textContent=dirty?'Draft autosaved locally · save a file for handoff':'Project file saved';$('status').textContent=errors.length?`${errors.length} issue${errors.length===1?'':'s'} to resolve`:'Ready';renderValidation(errors);renderOutline();if(rebuild)renderGraph();if(inspect)renderInspector();
 clearTimeout(draftTimer);if(!storageBlocked)draftTimer=setTimeout(()=>{try{localStorage.setItem(KEY,JSON.stringify(doc));}catch{$('autosave-state').textContent='Browser storage unavailable · save a project file';}},300);
 if(view.mode==='preview')renderPreview();
}
function select(kind,id='',switchMode=false,parent=''){selected={kind,id,parent};if(kind==='dialogue')activeDialogue=id;if(kind==='line')activeDialogue=talkFor(id,parent)?.id||'';if(switchMode){if(kind==='quest'||kind==='objective')view.mode='quests';else if(kind==='dialogue'||kind==='line')view.mode='dialogue';else if(kind==='beat'||kind==='chapter')view.mode='story';}renderOutline();renderInspector();renderGraph();setMode(view.mode,false);}
function mutate(run,{inspect=true,fit=false}={}){const before=copy(doc),selection={...selected},oldForward=forward;try{checkpoint();const value=run();change(true,inspect);if(fit)fitGraph();return value;}catch(e){doc=before;selected=selection;back.pop();forward=oldForward;change(true,true);toast(e.message);}}
function field(parent,label,key,obj,{type='text',options,min,max,step=1,help,commit,onchange,placeholder,readonly=false,ephemeral=false}={}){
 const l=el('label','',label),input=el(options?'select':type==='textarea'?'textarea':'input');input.id='field-'+(++fieldSerial);if(!options&&type!=='textarea')input.type=type;
 if(options)for(const option of options){const [value,name]=Array.isArray(option)?option:[option,friendly[option]||option];const o=el('option','',name);o.value=value;input.append(o);}if(min!==undefined)input.min=min;if(max!==undefined){if(type==='number')input.max=max;else input.maxLength=max;}if(type==='number')input.step=step;if(placeholder)input.placeholder=placeholder;input.readOnly=readonly;input.value=obj[key]??'';l.append(input);parent.append(l);if(help)hint(parent,help);
 if(readonly)return input;let editing=false;input.onfocus=()=>{editing=false;};const update=()=>{try{if(!editing&&!ephemeral){checkpoint();editing=true;}const v=type==='number'?(input.value===''?0:Number(input.value)):input.value;if(commit)commit(v);else obj[key]=v;if(onchange)onchange(v);if(!ephemeral)change(true,!!onchange);}catch(e){toast(e.message);input.value=obj[key]??'';}};input.addEventListener(options||commit?'change':'input',update);return input;
}
function check(parent,label,key,obj){const l=el('label','check'),i=el('input');i.type='checkbox';i.checked=!!obj[key];i.onchange=()=>mutate(()=>obj[key]=i.checked,{inspect:false});l.append(i,document.createTextNode(label));parent.append(l);return i;}
function options(kind,zero='Choose a target…'){const list=kind==='objective'?doc.native.quests.flatMap(q=>q.objectives):doc.native[kind]||[];return [["0",zero],...list.map(x=>[x.id,titleOf(kind,x)+' · '+x.id])];}
function chapterField(parent,obj){field(parent,'Chapter','chapter',obj,{options:doc.chapters.map(c=>[c.id,c.title])});}
function idNote(parent,item){hint(parent,'ID '+item.id,'id');}
function removeItem(parent,kind,item){parent.append(button('Delete '+labels[kind].toLowerCase(),()=>mutate(()=>{const r=Story.deleteItem(doc,kind,item.id,selected.parent);if(!r.ok)throw new Error(r.error);selected={kind:'project',id:''};toast('Removed. Undo restores it.');}), 'danger wide'));}
function listCard(parent,text,open,remove){const c=el('div','item-card'),h=el('div','card-head');h.append(button(text,open,'quiet'));if(remove)h.append(button('×',remove,'remove'));c.append(h);parent.append(c);return c;}
function renderOutline(){
 const out=$('outline');out.replaceChildren();const query=$('search').value.trim().toLowerCase();
 function item(kind,x,depth=0){if(query&&!`${titleOf(kind,x)} ${x.body||x.summary||''}`.toLowerCase().includes(query))return;const b=button('',()=>select(kind,x.id,true),'outline-item'+(selected.kind===kind&&selected.id===x.id?' selected':''));b.style.paddingLeft=(7+depth*12)+'px';const dot=el('span','item-dot');dot.style.background=kind==='quest'?'#d6ba7a':kind==='dialogue'?'#9fc4d6':'#a0c9aa';const t=el('span','item-text',titleOf(kind,x));if(kind!=='chapter')t.append(el('small','',labels[kind]));b.append(dot,t);out.append(b);}
 const section=(name,count,add)=>{const g=el('div','outline-group'),h=el('div','outline-heading');h.append(el('span','',name),el('span','count',String(count)));if(add)h.append(button('＋',add,'mini'));g.append(h);out.append(g);};
 for(const c of doc.chapters){section(c.title,doc.beats.filter(b=>b.chapter===c.id).length+doc.native.quests.filter(q=>q.chapter===c.id).length+doc.native.dialogues.filter(t=>t.chapter===c.id).length);item('chapter',c);for(const b of doc.beats.filter(x=>x.chapter===c.id))item('beat',b,1);for(const q of doc.native.quests.filter(x=>x.chapter===c.id))item('quest',q,1);for(const t of doc.native.dialogues.filter(x=>x.chapter===c.id))item('dialogue',t,1);}
 for(const [kind,name]of [['entity','Scene cast'],['flag','Story flags'],['counter','Counters & rewards'],['rule','Event rules'],['trigger','World triggers'],['encounter','Encounters']]){const entries=doc.native[collection[kind]];section(name,entries.length,()=>add(kind));for(const x of entries)item(kind,x);}
}
function add(kind){mutate(()=>{let v;if(kind==='chapter')v=Story.makeChapter(doc);else if(kind==='beat')v=Story.makeBeat(doc,currentChapter());else if(kind==='quest')v=Story.makeQuest(doc,currentChapter());else if(kind==='dialogue')v=Story.makeDialogue(doc,currentChapter());else if(kind==='entity')v=Story.makeEntity(doc);else if(kind==='flag')v=Story.makeFlag(doc);else if(kind==='counter')v=Story.makeCounter(doc);else if(kind==='rule')v=Story.makeRule(doc);else if(kind==='trigger'){if(doc.native.triggers.length>=64)throw new Error('The engine supports at most 64 world triggers.');v={id:Story.nextId(doc),name:'New world trigger',entity:'0',shape:'Box',center:{x:0,y:0,z:0},extent:{x:2,y:2,z:2},once:true};doc.native.triggers.push(v);}else if(kind==='encounter'){if(doc.native.encounters.length>=16)throw new Error('The engine supports at most 16 encounters.');v={id:Story.nextId(doc),name:'New encounter',arena:doc.native.entities[0]?.id||'0',training:false,actors:[]};doc.native.encounters.push(v);}selected={kind,id:v.id};if(kind==='quest')view.mode='quests';if(kind==='dialogue'){view.mode='dialogue';activeDialogue=v.id;}if(kind==='beat'||kind==='chapter')view.mode='story';},{fit:true});setMode(view.mode,false);}
function renderInspector(){
 fieldSerial=0;const out=$('inspector');out.replaceChildren();let item=locate(selected.kind,selected.id);if(!item){selected={kind:'project',id:''};item=doc;}const kind=selected.kind;$('selection-kind').textContent=labels[kind].toUpperCase();out.append(el('h2','',kind==='project'?'Shape the journey':titleOf(kind,item)));
 const descriptions={project:'Plan the arc, then connect it to quests and branching conversations.',chapter:'A chapter groups your story beats, quests and dialogue. Chapters are planning content.',beat:'Write a moment, a discovery or a choice. Links describe the story flow; gameplay uses quests and event rules.',quest:'A playable promise with measurable objectives. Its progress is driven by game events.',dialogue:'A speaker, an entry line and choices that can change the world.',line:'Write what the NPC says, then give the player meaningful choices.',entity:'Bind a character or object to its persistent scene ID. Names alone do not bind to the game.',rule:'When an event passes these conditions, perform these actions.'};hint(out,descriptions[kind]||'Edit the values used by the engine gameplay document.','sub');
 if(kind==='project'){field(out,'Story title','title',doc,{max:96,commit:v=>{doc.title=v;doc.native.name=v;}});field(out,'One sentence premise','logline',doc,{type:'textarea',max:4096});field(out,'Engine gameplay name','name',doc.native,{max:96});const s=Story.summary(doc);const stats=el('div','item-card');stats.append(el('div','card-head',`${s.chapters} chapters · ${s.quests} quests · ${s.dialogues} conversations`));hint(stats,`${s.beats} story beats · ${s.objectives} objectives · ${s.rules} event rules`);out.append(stats);hint(out,'Export creates a native .gameplay file. The running world must also have a Components manifest, matching scene IDs and a gameplay host. Dedicated environment playtests currently keep story logic frozen.','inline-help');heading(out,'Start writing');out.append(button('＋ Add a story beat',()=>add('beat'),'wide'));out.append(button('＋ Add a scene character / object',()=>add('entity'),'wide'));return;}
 idNote(out,item);
 if(kind==='chapter'){field(out,'Chapter title','title',item,{max:96});field(out,'Purpose & summary','summary',item,{type:'textarea',max:8192});heading(out,'Chapter contents');const members=[...doc.beats.filter(x=>x.chapter===item.id).map(x=>['beat',x]),...doc.native.quests.filter(x=>x.chapter===item.id).map(x=>['quest',x]),...doc.native.dialogues.filter(x=>x.chapter===item.id).map(x=>['dialogue',x])];for(const [k,x]of members)out.append(button(titleOf(k,x),()=>select(k,x.id,true),'wide'));if(!members.length)hint(out,'This chapter is ready for its first beat.');}
 if(kind==='beat'){field(out,'Beat title','title',item,{max:96});chapterField(out,item);field(out,'What happens here?','body',item,{type:'textarea',max:16384});heading(out,'Next story beats');for(const id of item.next){const n=locate('beat',id);listCard(out,n?.title||id,()=>select('beat',id),()=>mutate(()=>item.next=item.next.filter(x=>x!==id)));}const candidates=doc.beats.filter(b=>b.id!==item.id&&!item.next.includes(b.id));if(candidates.length){const holder={target:candidates[0].id};const input=field(out,'Link a following beat','target',holder,{options:candidates.map(b=>[b.id,b.title]),ephemeral:true});out.append(button('＋ Link beat',()=>mutate(()=>{if(item.next.length>=16)throw new Error('A story beat supports at most 16 links.');if(!item.next.includes(input.value))item.next.push(input.value);}), 'wide'));}else hint(out,'Add another beat to connect this moment to the next.');hint(out,'Story links can branch or loop. They do not run game events automatically.');}
 if(kind==='quest')renderQuest(out,item);
 if(kind==='objective')renderObjective(out,item);
 if(kind==='dialogue')renderDialogue(out,item);
 if(kind==='line')renderLine(out,item);
 if(kind==='entity'){field(out,'Name','name',item,{max:96});field(out,'Persistent scene ID','id',item,{commit:value=>remapEntity(item,value),help:'Paste the existing scene entity’s unsigned 64-bit ID. Kept as text to preserve all digits.'});check(out,'Initially active','active',item);vectorFields(out,'Declared position / fallback',item.position);hint(out,'Adding an entity declaration does not create or move a 3D model. Match this ID to an existing scene entity.','inline-help');}
 if(kind==='flag'){field(out,'Flag name','name',item,{max:96});check(out,'Initially true','initial',item);hint(out,'Use flags for decisions, one-time rewards and remembered choices. Conditions test them; actions change them.');}
 if(kind==='counter'){field(out,'Counter name','name',item,{max:96});field(out,'Initial value','initial',item,{type:'number',min:-1000000,max:1000000});const pair=el('div','two-cols');out.append(pair);field(pair,'Minimum','minimum',item,{type:'number',min:-1000000,max:1000000});field(pair,'Maximum','maximum',item,{type:'number',min:-1000000,max:1000000});hint(out,'Counters can represent progress, reputation or a numeric reward. They do not grant inventory items or equipment.','inline-help');}
 if(kind==='rule')renderRule(out,item);
 if(kind==='trigger'){field(out,'Trigger name','name',item,{max:96});field(out,'Attach to scene entity','entity',item,{options:options('entities','World space (no entity)')});field(out,'Shape','shape',item,{options:Story.SHAPES});vectorFields(out,'Center / entity-relative offset',item.center);vectorFields(out,'Extent (sphere uses X as radius)',item.extent,.01);check(out,'Fire only once','once',item);hint(out,'Trigger coordinates define logic volumes. They do not add a visible mesh.');}
 if(kind==='encounter'){field(out,'Encounter name','name',item,{max:96});field(out,'Arena scene entity','arena',item,{options:options('entities')});check(out,'Training encounter','training',item);heading(out,'Encounter actors');for(const id of item.actors)listCard(out,locate('entity',id)?.name||id,()=>select('entity',id),()=>mutate(()=>item.actors=item.actors.filter(x=>x!==id)));const choices=doc.native.entities.filter(e=>!item.actors.includes(e.id));if(choices.length){const holder={target:choices[0].id};const input=field(out,'Add actor','target',holder,{options:choices.map(x=>[x.id,x.name]),ephemeral:true});out.append(button('＋ Add actor',()=>mutate(()=>{if(item.actors.length>=16)throw new Error('An encounter supports at most 16 actors.');item.actors.push(input.value);}),'wide'));}hint(out,'Only supported combat hosts can start authored encounters. Current game support is limited to its existing training and presentation encounter.','inline-help');}
 removeItem(out,kind,item);
}
function vectorFields(parent,label,obj,min=-10000000){heading(parent,label);const row=el('div','three-cols');parent.append(row);for(const k of ['x','y','z'])field(row,k.toUpperCase(),k,obj,{type:'number',step:.1,min,max:10000000});}
function remapEntity(entity,value){if(!/^[1-9]\d{0,19}$/.test(value)||BigInt(value)>18446744073709551615n)throw new Error('Use an unsigned 64-bit scene ID greater than zero.');if(doc.native.entities.some(e=>e!==entity&&e.id===value))throw new Error('That scene ID is already declared.');const old=entity.id;entity.id=value;for(const q of doc.native.quests)for(const o of q.objectives)if(o.entity===old)o.entity=value;for(const t of doc.native.dialogues)if(t.speaker===old)t.speaker=value;for(const t of doc.native.triggers)if(t.entity===old)t.entity=value;for(const e of doc.native.encounters){if(e.arena===old)e.arena=value;e.actors=e.actors.map(x=>x===old?value:x);}for(const r of doc.native.rules)if(r.entity===old)r.entity=value;for(const lists of [...doc.native.rules,...doc.native.dialogues.flatMap(t=>t.lines.flatMap(l=>l.choices))]){for(const c of lists.conditions)if(c.kind==='EntityActive'&&c.key===old)c.key=value;for(const a of lists.actions)if(a.kind==='ActivateEntity'&&a.key===old)a.key=value;}selected.id=value;}
function renderQuest(out,q){field(out,'Quest name','name',q,{max:96});chapterField(out,q);heading(out,'Objectives',()=>mutate(()=>{const o=Story.addObjective(doc,q.id);selected={kind:'objective',id:o.id};}), '＋ Objective');for(const o of q.objectives){const card=listCard(out,o.text,()=>select('objective',o.id,true));hint(card,`${friendly[o.event]} · ${o.entity==='0'?'any entity':locate('entity',o.entity)?.name||o.entity} · target ${o.required}`);}hint(out,'Objectives progress while the quest is Active. Multiple objectives run concurrently; use rules and flags to gate sequential steps.');heading(out,'Quest giver & offer');const holder={speaker:doc.native.entities[0]?.id||'0'};const offerSpeaker=field(out,'Offer speaker','speaker',holder,{options:options('entities'),ephemeral:true});const offer=button('Create an accept / decline conversation',()=>mutate(()=>{if(offerSpeaker.value==='0')throw new Error('Add a scene entity, then choose it as the offer speaker.');const talk=Story.makeDialogue(doc,q.chapter);talk.speaker=offerSpeaker.value;talk.name='Offer · '+q.name;talk.lines[0].text='Will you help with '+q.name+'?';talk.lines[0].choices=[{text:'I will help.',next:'0',conditions:[{kind:'Quest',key:q.id,compare:'Equal',value:0}],actions:[{kind:'SetQuest',key:q.id,value:1}]},{text:'Maybe later.',next:'0',conditions:[],actions:[]}];const r=Story.makeRule(doc);r.name='Offer · '+q.name;r.event='Interact';r.entity=offerSpeaker.value;r.conditions=[{kind:'Quest',key:q.id,compare:'Equal',value:0}];r.actions=[{kind:'Speak',key:talk.id,value:1}];activeDialogue=talk.id;selected={kind:'dialogue',id:talk.id};view.mode='dialogue';}), 'wide');out.append(offer);hint(out,'Creates an Interact rule and a linked conversation. Accept activates this quest; decline leaves it inactive.');heading(out,'Completion reward');const reward={counter:doc.native.counters.find(c=>!doc.native.quests.some(x=>x.objectives.some(o=>o.counter===c.id)))?.id||'0',value:25};const ci=field(out,'Reward counter','counter',reward,{options:options('counters','Create a reward counter first'),ephemeral:true});const vi=field(out,'Amount to add','value',reward,{type:'number',min:-1000000,max:1000000,ephemeral:true});out.append(button('Create a one-time completion reward',()=>mutate(()=>{if(ci.value==='0')throw new Error('Create and choose a reward counter first.');if(!Number.isInteger(Number(vi.value)))throw new Error('Use a whole-number reward.');const r=Story.makeRule(doc);r.name='Reward · '+q.name;if(offerSpeaker.value==='0')throw new Error('Choose the quest giver before creating a return reward.');r.event='Interact';r.entity=offerSpeaker.value;r.key='0';r.once=true;r.conditions=[{kind:'Quest',key:q.id,compare:'Equal',value:2}];r.actions=[{kind:'AddCounter',key:ci.value,value:Number(vi.value)}];selected={kind:'rule',id:r.id};toast('Reward rule created. Return to the quest giver after completion to receive it once.');}), 'wide'));hint(out,'Return to the selected quest giver after completion to collect this counter reward once. Counters do not grant inventory items.');}
function renderObjective(out,o){const q=questFor(o.id);out.append(button('← '+q.name,()=>select('quest',q.id,true),'quiet'));field(out,'Objective text','text',o,{max:256});field(out,'Progress counter','counter',o,{options:options('counters'),help:'Every objective must own a different declared counter.'});field(out,'Required total','required',o,{type:'number',min:1,max:1000000});field(out,'Count this event','event',o,{options:Story.EVENTS.filter(x=>x!=='DialogueChoice')});field(out,'Matching entity','entity',o,{options:options('entities','Any entity')});const counter=locate('counter',o.counter);if(counter){out.append(button('Edit progress counter ↗',()=>select('counter',counter.id),'wide'));hint(out,`Counter range: ${counter.minimum}–${counter.maximum}. Increase its maximum if the required total is larger.`);}hint(out,'Objective events match their objective ID. Other event kinds match the event type and entity; use event rules for a specific trigger or encounter.');}
function renderDialogue(out,t){field(out,'Conversation name','name',t,{max:96});chapterField(out,t);field(out,'NPC / speaker','speaker',t,{options:options('entities')});field(out,'Entry line','entry',t,{options:t.lines.map(l=>[l.id,l.text.slice(0,60)||'Untitled line'])});heading(out,'Conversation lines',()=>mutate(()=>{const l=Story.makeLine(doc,t.id);selected={kind:'line',id:l.id,parent:t.id};}), '＋ Line');for(const l of t.lines){const c=listCard(out,(t.entry===l.id?'↳ ENTRY · ':'')+l.text.slice(0,85),()=>select('line',l.id,true,t.id));hint(c,`${l.choices.length} choice${l.choices.length===1?'':'s'} · ID ${l.id}`);}hint(out,'Each new line needs an incoming choice link. Export checks unreachable lines and dialogue cycles.');heading(out,'Open this conversation in game');out.append(button('Create an Interact → Speak rule',()=>mutate(()=>{const r=Story.makeRule(doc);r.name='Speak · '+t.name;r.entity=t.speaker;r.actions=[{kind:'Speak',key:t.id,value:1}];selected={kind:'rule',id:r.id};}), 'wide'));}
function renderLine(out,l){const t=talkFor(l.id);out.append(button('← '+t.name,()=>select('dialogue',t.id,true),'quiet'));field(out,'NPC dialogue','text',l,{type:'textarea',max:2048,help:'Native dialogue is a single-line text record. Use normal prose without line breaks.'});heading(out,'Player choices',()=>mutate(()=>{if(l.choices.length>=8)throw new Error('A line supports at most eight choices.');l.choices.push({text:'New response',next:'0',conditions:[],actions:[]});}), '＋ Choice');if(!l.choices.length)hint(out,'A line with no choices can be closed in preview. Add a choice for a branch or explicit goodbye.');l.choices.forEach((c,i)=>{const card=el('div','item-card'),h=el('div','card-head');h.append(el('span','',`CHOICE ${i+1}`),button('×',()=>mutate(()=>l.choices.splice(i,1)),'remove'));card.append(h);out.append(card);field(card,'Player response','text',c,{max:256});field(card,'Then go to','next',c,{options:[['0','End conversation'],...t.lines.filter(x=>x.id!==l.id).map(x=>[x.id,x.text.slice(0,60)])]});renderLists(card,c,true);});}
function targetKind(kind,action=false){const map=action?{SetFlag:'flags',SetCounter:'counters',AddCounter:'counters',Speak:'dialogues',ActivateEntity:'entities',StartEncounter:'encounters',StartTraining:'encounters',SetQuest:'quests',SetEncounter:'encounters',SetCooldown:'rules'}:{Flag:'flags',Counter:'counters',Quest:'quests',Encounter:'encounters',EntityActive:'entities',CooldownReady:'rules'};return map[kind];}
