 for(const edge of graphEdges){const a=byKey.get(edge.from),b=byKey.get(edge.to);if(!a||!b)continue;const x=a.position.x+220,y=a.position.y+48,tx=b.position.x,ty=b.position.y+48,curve=Math.max(65,Math.abs(tx-x)*.45);svg('path',{d:`M ${x} ${y} C ${x+curve} ${y},${tx-curve} ${ty},${tx} ${ty}`,class:'graph-edge'+(edge.note?' note':'')},edges);if(edge.label){const t=svg('text',{x:(x+tx)/2,y:(y+ty)/2-8,class:'edge-label','text-anchor':'middle'},edges);t.textContent=edge.label;}}
