 const values=el('section','preview-card');values.append(el('h3','','Flags & counters'));right.append(values);for(const f of doc.native.flags){const row=el('div','preview-state');row.append(el('span','',f.name),el('strong','',preview.flags[f.id]?'True':'False'));values.append(row);}for(const c of doc.native.counters){const row=el('div','preview-state');row.append(el('span','',c.name),el('strong','',String(preview.counters[c.id])));values.append(row);}if(!doc.native.flags.length&&!doc.native.counters.length)hint(values,'No flags or counters declared.');
 if(doc.beats.length){const story=el('section','preview-card'),beat=doc.beats.find(b=>b.id===storyAt)||doc.beats[0];story.append(el('h3','','Story walkthrough · planning only'),el('div','section-label',beat.title),el('p','story-preview-body',beat.body));const links=el('div','story-preview-links');for(const id of beat.next){const next=doc.beats.find(b=>b.id===id);if(next)links.append(button(next.title,()=>{storyAt=id;renderPreview();}));}if(!beat.next.length)hint(story,'End of this story path. Restart preview to return to the first beat.');story.append(links);left.append(story);}
